INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e97347e6-b638-48c2-9824-dd5165151a80', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$91. óra: Feladatmegoldás$q$, $q$Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "a0853a02-c169-4278-bb8b-c7f664b1e5aa", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "d6b20749-2291-4695-a146-41220669f624", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "bf1029b0-1d5b-4251-a8bb-0cd31a204e76", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "a361ca41-5804-4ee0-a85a-e27987757d2f", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "d74986fc-0ad4-4c7f-b88a-64368b554642", "text": "Igaz", "isCorrect": true}, {"id": "4bbd3d80-484e-4b41-a1ff-3ff4d260b7f7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca2f99b9-4450-44e9-a1bd-d6fc0be4a863", "text": "Melyik egyenlet írja le: 'Egy szám 4-szeresénél 5-tel több a 25'? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "d063d9c5-e59c-4e39-a6d1-5a94ba749b80", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "ef55d6c9-f38d-4914-befd-13ce26633b4a", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "bf70e2fa-e032-457b-98a2-4eb20d7d64ac", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "4ebf488f-5c68-447c-855b-1d74f8f22bd4", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "913fc3e9-c075-4ef2-998f-c99cfa963e9f", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5913867b-e5b0-4f74-b422-68e8f6e02e4b", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "e3c15a74-5153-4ade-89d4-411fcaf1e1fb", "text": "Igaz", "isCorrect": true}, {"id": "ec051a3b-03e4-4541-a2ed-7b347500de32", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('20ea0db1-9503-4902-8e04-be0575cdd2b1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$92. óra: Több megoldás is lehet$q$, $q$Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "39d3936c-9710-4ee5-8a0c-6e002869c031", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "21f38bf2-1125-4b17-b608-55f53150c771", "text": "Mely kifejezés jelenti azt, hogy 'legfeljebb 5'?", "type": "multiple-choice", "options": [{"id": "1e23116e-a82b-4c76-8f56-b8edc9aa0578", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "66a1ea38-c6b4-40c7-96b6-e0e701ec299c", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "d47d6a3f-5d5a-4e27-a7ae-7e3bfb986ed2", "text": "Pontosan 5", "isCorrect": false}, {"id": "e3dbb8d2-ef2c-46b8-ac79-e74e29db021d", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "90fb97b4-15d4-4dde-9ade-5a19ce096fa8", "text": "Mely kifejezés jelenti azt, hogy 'legalább 5'?", "type": "multiple-choice", "options": [{"id": "31feb97d-9763-4a9d-9fef-976361bb4387", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "00beb9d7-60ff-4786-8aa6-97139444854c", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "35d4f531-784c-47c6-bad0-8b0991e5fd03", "text": "Pontosan 5", "isCorrect": false}, {"id": "55e94988-13b2-4b6f-9287-e1222d0f156e", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "d65b8fad-b9b6-4448-a286-da349ce9f468", "text": "A 'legalább 3 és legfeljebb 6' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "acc6b011-248b-4a07-9818-6882ef78947a", "text": "Igaz", "isCorrect": true}, {"id": "0975e97a-c674-42b6-b590-f66f7a424471", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4b8eeb3-63df-40e5-8f93-dcf7e8e4a58d", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5f937d39-ac80-4f47-b049-8152597a5800", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "4a68f4fd-b67b-4dcc-81dc-9230bf0bbc26", "text": "Igaz", "isCorrect": true}, {"id": "0cd5885d-8506-4dcd-9517-0e4ceaafa0f8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66dbfe74-67b5-482c-8909-affffe589cd6", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50341177-dc0e-43d0-ba92-cf4fa27b6237', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$93. óra: Létraverseny II.$q$, $q$Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "f0f9e995-7145-48fe-8ea8-46945a451ff2", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "45497675-e6cd-482d-8923-f8787541ae2a", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "094b8f84-2e9a-4742-9b72-5c2c31214c8c", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "b2097881-c2ad-45e1-a840-09fd22d8c25b", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "68b10ab7-78c2-4100-94fa-070be00238d9", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "44a38c2f-75bb-4aa4-b1c0-fb94eba774be", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "b00bad17-31dc-4368-b51b-4cf4d6e7b15d", "text": "Igaz", "isCorrect": true}, {"id": "343311c9-5119-4fa2-bb1a-94fdc8b9ac36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b71177b3-b990-4126-8515-b5c1bbb0f17f", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0a982ce8-49a9-4032-bdd9-8ac95b0c80bf', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$94. óra: Összefoglalás$q$, $q$A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "037c9bfc-1fed-4667-b5d4-bbcb3238ca9e", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "50d6726b-2ede-4ae5-8836-7ef428abad26", "text": "1 : 3", "isCorrect": true}, {"id": "4dff966d-12fa-4763-a006-15e8cac66ec5", "text": "1 : 4", "isCorrect": false}, {"id": "a475c25c-52ad-4039-93d5-7f8fa2a874e7", "text": "2 : 3", "isCorrect": false}, {"id": "c918b839-f503-44c5-8f05-248bd1dbf65c", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "b974a724-1824-4d90-8aaf-e6e0259e830e", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "93622b83-9cc6-4b35-885c-62163d34355d", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "a7cfa4dd-5165-4159-aa16-cba079fcf3c9", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "8b2c40eb-325c-4287-bf3a-678960c173d0", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d38fa114-a4f9-4083-af83-d85aa5c8b52c", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "0cd5c430-f7d8-40ec-9f1a-3817738ce16d", "text": "Igaz", "isCorrect": true}, {"id": "63956204-d4f7-4ab6-b8e9-e7ef260f16a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ace8782-42e2-460c-9fb9-cd559744af7f", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1a45bc56-0f3f-4bfe-bbcb-8c5c95f290d6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$95. óra: Gyakorlóóra$q$, $q$Gyakorló feladatok önállóan, becslés és ellenőrzés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "2ee41c73-ff08-45f0-b46e-1b8916d2569e", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "0fd97267-f43b-46ee-aebb-fa6d4b82f97a", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "4134bae8-c955-44ce-b938-d95eff33baa2", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "583de0e7-b4ed-4d32-9940-3e95aea7d20e", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "d37f06ae-a0e5-4af2-8e1d-d966f908b300", "text": "Igaz", "isCorrect": true}, {"id": "29ecbc32-b06b-43cb-9e5b-7814afe4f736", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "34dc2369-a0da-47eb-83e5-4f9ccc303ca8", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2361ec77-0123-403c-8e26-603191cb9506", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "54720fee-1741-40ba-9d85-6f724298403c", "text": "Igaz", "isCorrect": true}, {"id": "efc3a500-d5a8-43be-badd-461076b10696", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "51e8a072-02b4-4344-b65a-e0aa0e86776b", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4392f5d6-0867-40db-8267-17ee59010106', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$96. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "5f6f13a9-515e-44d8-ac8f-c34aecda6eeb", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "7935a9d2-2207-4653-b0cf-e5c0f6f7b9c3", "text": "2 : 7", "isCorrect": true}, {"id": "3f686203-dd48-48e9-bf39-5f5c2a1bdbbc", "text": "1 : 35", "isCorrect": false}, {"id": "f3721026-25a6-44c2-a393-7509575c0ad5", "text": "2 : 5", "isCorrect": false}, {"id": "c31b39ed-900a-4058-a4d1-88bdfea460d9", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "1900ac38-9a9a-408f-a69b-eb946e3f40de", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "5ea8a87f-f78c-4d7d-a2e3-2091f29f6a3f", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "16fb474d-c6b6-4a7c-8748-dab072630cfa", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "c9e5db86-16f8-4b69-9670-ddfb32e61a9a", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "99a79607-5f29-4770-976b-10cf82d1a5dc", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "00a842c4-13ef-4779-9c0d-db2b12c66921", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "c472693c-84a6-4944-9b05-513b12d81b43", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "1b0638f4-a04e-4542-8b19-be45c92a5eb1", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "124be3f8-ef38-4a8e-bf05-472cf4d56305", "text": "Igaz", "isCorrect": true}, {"id": "48cad333-0a95-4222-97fa-db65d16a2c50", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20fa208d-aa39-4adc-84ec-ff0768404659", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c12f6911-9bd3-49ec-8812-ea5515d7e9ab', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$97. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "eaabf3d8-5a1b-42c3-9536-f845671f32e1", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "0ab05dfd-315b-4dbb-b7b1-9891e1999491", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "0915533e-2363-4243-996f-bbe68045d958", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "71b015b7-a79d-4945-bd9c-3b09780f4f89", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "b46ce740-84fc-4734-9ef2-f226b512907f", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "4d7f2a69-8077-4410-8d12-01df5c7b6c90", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "4808cfdf-a49f-461b-b32b-499287cac497", "text": "Igaz", "isCorrect": true}, {"id": "dada201c-fe77-4966-9ed2-53f844f4aa98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "672d65df-b6ad-41fc-aa38-9bbc5c544430", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "d4c9c1b5-528e-4d4c-a234-8b122e844b4f", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "11c91d7c-305e-4b45-b020-19fe7d596226", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "87354750-e82d-4754-bda3-bb11a4b94966", "text": "Igaz", "isCorrect": true}, {"id": "6d356e91-243e-43e4-96b7-930c3160904d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a512e133-07ad-4f0f-a26e-40bfc82db1ae", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "6d849992-9d16-4886-bb38-38920a5a294f", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9255d4ac-dec0-4f4f-bf3c-a7b978b4d34a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$98. óra: Hosszúság, tömeg, idő$q$, $q$A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "ed7e7966-1538-41ec-a94b-74ae00023bae", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "3ee1c7da-5cbe-4901-92dc-ffb857c10e94", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "2d07d963-ec43-474f-b381-bd529a577312", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "4a1b7039-7d8c-437e-a0c5-f36d0a815b67", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "a89566f1-d0f9-4061-8d70-9ec1b376caf3", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "02f828ee-f4b3-460d-87e8-5889e2e0dcab", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "43502ebf-e945-4995-a735-cf5b47aa5c6a", "text": "Igaz", "isCorrect": true}, {"id": "2d309272-ed37-4f06-8592-8b0541cce0cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a87316d-a72e-43b0-b18a-0cb2bdf1e749", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dddcc80b-dc14-4430-b48e-5fcbd8b202b2', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$99. óra: Hosszúság, tömeg, idő II.$q$, $q$Összetett mértékegység-átváltási feladatok és gyakorlás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "7fda56d7-9f32-41aa-9c5b-460556747a1c", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "71f91941-dd74-491b-9f7f-72438af8ff34", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "ee94c173-affe-4237-b667-d894f219fa33", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "41e5a1f3-2cbb-44a6-bd50-7862fde44a8b", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "97eb25a3-419d-4950-b239-49c54687d88f", "text": "Igaz", "isCorrect": true}, {"id": "c2507227-595b-4c3a-b7f6-e5ce696fed04", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6641da5b-c12b-46c1-988b-a510c3be1473", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "16cfddd8-4062-4847-a99e-a68e472da856", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "41017912-7c3c-48f7-9888-a1bd0372c1a1", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "e24c1cf3-7772-44d7-ae3a-7116f2efdbc4", "text": "Igaz", "isCorrect": true}, {"id": "6c83ae16-e29f-465c-9b60-68bd1aa06433", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('37e10b10-c67d-4566-9586-43b76715e784', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$100. óra: A sokszögek kerülete$q$, $q$Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "5213b9ce-7bb3-450d-a731-4d6577a7c6dc", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "dae641f7-91a2-4db6-965a-56f060220503", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "6422ddaa-6a91-487f-b226-c4dc96103b6c", "text": "K = a * b", "isCorrect": false}, {"id": "cdde9d51-ac2f-48dd-a71a-50f50ae609e0", "text": "K = a + b", "isCorrect": false}, {"id": "d07a219e-ae12-460f-bb9f-42288db8c9f2", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "548f912d-4b48-44aa-8548-d8678220ee49", "text": "Mi a négyzet kerületének képlete ('a' oldallal)?", "type": "multiple-choice", "options": [{"id": "a60064a3-ce26-44e4-9831-4cfc32c28058", "text": "K = 4 * a", "isCorrect": true}, {"id": "7d7c3724-bd9a-42c1-89c3-9deddfbfbeb2", "text": "K = a * a", "isCorrect": false}, {"id": "424247ce-4e03-4fa8-97c6-5ee402b97c40", "text": "K = 2 * a", "isCorrect": false}, {"id": "199b095d-ccc5-4452-b307-9d81e68876e0", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "5b480e31-a9ff-4e1e-959c-f3fae618200e", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "8d9c7352-427a-40a4-9ee2-bedde50052d3", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "ccd8964a-3a30-4a78-81d1-eae5abde42ec", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d88dbb20-dd3b-4458-99bd-32de2a8ea24c", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "b88c4b37-3434-4134-826b-8690901c9942", "text": "Igaz", "isCorrect": true}, {"id": "150e6bb4-85e0-4f41-92c7-1059511ca1c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b01bfd5a-46ef-4d19-bd03-5e4f1b4b5cd4", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;